Date: Tue, 24 Nov 2026 23:22:41 +0100
Subject: [PATCH] widgets: show where an app comes from when its name is
 ambiguous

An app installed both from the distribution and as a Flatpak or Snap
had identical entries in the Open With menu and dialog. Those copies now
say (Flatpak) or (Snap) after their name, so they can be told apart.

BUG: 459653
---
 src/widgets/applicationsource_p.h | 48 +++++++++++++++++++++++++++++++
 src/widgets/kfileitemactions.cpp  | 12 +++++---
 src/widgets/kfileitemactions_p.h  |  2 +-
 src/widgets/kopenwithdialog.cpp   | 16 +++++++++--
 4 files changed, 71 insertions(+), 7 deletions(-)
 create mode 100644 src/widgets/applicationsource_p.h

diff --git a/src/widgets/applicationsource_p.h b/src/widgets/applicationsource_p.h
new file mode 100644
index 000000000..7a0cba907
--- /dev/null
+++ b/src/widgets/applicationsource_p.h
@@ -0,0 +1,48 @@
+/*
+    This file is part of the KDE project
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#ifndef APPLICATIONSOURCE_P_H
+#define APPLICATIONSOURCE_P_H
+
+#include <KLocalizedString>
+#include <KService>
+
+#include <QHash>
+#include <QSet>
+
+namespace KIO
+{
+// Names used by more than one of the given services, e.g. an app installed both from the distribution and as a Flatpak
+inline QSet<QString> ambiguousServiceNames(const KService::List &services)
+{
+    QHash<QString, int> count;
+    for (const KService::Ptr &service : services) {
+        ++count[service->name()];
+    }
+    QSet<QString> names;
+    for (auto it = count.cbegin(); it != count.cend(); ++it) {
+        if (it.value() > 1) {
+            names.insert(it.key());
+        }
+    }
+    return names;
+}
+
+// The service's name, followed by where it was installed from when that isn't the distribution
+inline QString serviceNameWithSource(const KService::Ptr &service)
+{
+    if (!service->property<QString>(QStringLiteral("X-Flatpak")).isEmpty()) {
+        return i18nc("@item %1 is an application name", "%1 (Flatpak)", service->name());
+    }
+    if (!service->property<QString>(QStringLiteral("X-SnapInstanceName")).isEmpty()) {
+        return i18nc("@item %1 is an application name", "%1 (Snap)", service->name());
+    }
+    return service->name();
+}
+}
+
+#endif
