@@ -879,9 +880,12 @@ void KFileItemActionsPrivate::insertOpenWithActionsTo(QAction *before, QMenu *to
     QObject::connect(openWithAct, &QAction::triggered, this, &KFileItemActionsPrivate::slotOpenWithDialog);

