From dc5dd01ad81c64d2d9967ce9160479a669ffccf9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:22:42 +0100
Subject: [PATCH] runners/services: show where an app comes from if its name is
 ambiguous

An app installed both from the distribution and as a Flatpak or Snap
gave several identical search results, so there was no way to tell which
was which. Those copies now say (Flatpak) or (Snap) after their name.

BUG: 459653
---
 runners/services/servicerunner.cpp | 18 +++++++++++++++++-
 1 file changed, 17 insertions(+), 1 deletion(-)

diff --git a/runners/services/servicerunner.cpp b/runners/services/servicerunner.cpp
index 8fd7105edf..9978328015 100644
--- a/runners/services/servicerunner.cpp
+++ b/runners/services/servicerunner.cpp
@@ -196,6 +196,13 @@ public:
         : m_runner(runner)
         , m_services(list)
     {
+        QSet<QString> names;
+        for (const KService::Ptr &service : list) {
+            if (names.contains(service->name())) {
+                m_ambiguousNames.insert(service->name());
+            }
+            names.insert(service->name());
+        }
     }

     void match(KRunner::RunnerContext &context)
@@ -245,7 +252,15 @@ private:
     {
         const QString name = service->name();

-        match.setText(name);
+        if (!m_ambiguousNames.contains(name)) {
+            match.setText(name);
+        } else if (!service->property<QString>(u"X-Flatpak"_s).isEmpty()) {
+            match.setText(i18nc("Search result, %1 is an application name", "%1 (Flatpak)", name));
+        } else if (!service->property<QString>(u"X-SnapInstanceName"_s).isEmpty()) {
+            match.setText(i18nc("Search result, %1 is an application name", "%1 (Snap)", name));
+        } else {
+            match.setText(name);
+        }

         QUrl url;
         url.setScheme(QStringLiteral("applications"));
@@ -506,6 +521,7 @@ private:
     ServiceRunner *m_runner;
     QSet<QString> m_seen;
     const QList<KService::Ptr> m_services;
+    QSet<QString> m_ambiguousNames;

     QList<KRunner::QueryMatch> matches;
     QString query;
-- 
2.53.0

