Subject: [PATCH] appchooser: show where an app comes from when its name is
 ambiguous

An app installed both from the distribution and as a Flatpak or Snap
showed up several times with the same name in the app chooser, so there
was no way to tell them apart. Those copies now say (Flatpak) or (Snap).

BUG: 459653
---
 src/appchooserdialog.cpp | 28 ++++++++++++++++++++++++++--
 1 file changed, 26 insertions(+), 2 deletions(-)

diff --git a/src/appchooserdialog.cpp b/src/appchooserdialog.cpp
index 66ed8f11..8f6dd84d 100644
--- a/src/appchooserdialog.cpp
+++ b/src/appchooserdialog.cpp
@@ -548,6 +548,24 @@ void AppModel::loadApplications()
     const KService::List appServices = KApplicationTrader::query([](const KService::Ptr &service) -> bool {
         return service->isValid();
     });
+
+    const auto displayName = [](const KService::Ptr &service) {
+        const QString fullName = service->property<QString>(QStringLiteral("X-GNOME-FullName"));
+        return fullName.isEmpty() ? service->name() : fullName;
+    };
+    QSet<QString> names;
+    QSet<QString> ambiguousNames;
+    for (const KService::Ptr &service : appServices) {
+        if (service->noDisplay() && !service->aliasFor().isEmpty()) {
+            continue;
+        }
+        const QString name = displayName(service);
+        if (names.contains(name)) {
+            ambiguousNames.insert(name);
+        }
+        names.insert(name);
+    }
+
     for (const KService::Ptr &service : appServices) {
         if (service->noDisplay()) {
             if (const auto alias = service->aliasFor(); !alias.isEmpty()) {
@@ -556,8 +574,14 @@ void AppModel::loadApplications()
             }
         }

-        const QString fullName = service->property<QString>(QStringLiteral("X-GNOME-FullName"));
-        const QString name = fullName.isEmpty() ? service->name() : fullName;
+        QString name = displayName(service);
+        if (ambiguousNames.contains(name)) {
+            if (!service->property<QString>(QStringLiteral("X-Flatpak")).isEmpty()) {
+                name = i18nc("@item %1 is an application name", "%1 (Flatpak)", name);
+            } else if (!service->property<QString>(QStringLiteral("X-SnapInstanceName")).isEmpty()) {
+                name = i18nc("@item %1 is an application name", "%1 (Snap)", name);
+            }
+        }
         ApplicationItem appItem(name, service);

         if (!m_list.contains(appItem)) {
